    this.verbose = false

    this.startedAt = null
    this.finishedAt = null
    this.elapsed = null

    /** @type {string[]} */
    this.authorsRemovedFromBooks = []
    /** @type {Set<string>} */
    this.authorsNumBooksChangedIds = new Set()
    /** @type {string[]} */
    this.seriesRemovedFromBooks = []

    this.logs = []
  }

