211	      existingLibraryItem.ctime = this.ctimeMs
212	      this.hasChanges = true
213	    }
214	    if (existingLibraryItem.isMissing) {
215	      libraryScan.addLog(LogLevel.DEBUG, `Library item "${existingLibraryItem.relPath}" was missing but now found`)
216	      existingLibraryItem.isMissing = false
217	      this.hasChanges = true
218	    }
219	
220	    this.libraryFilesRemoved = []
221	    this.libraryFilesModified = []
222	    let libraryFilesAdded = this.libraryFiles.map(lf => lf)
223	
224	    for (const existingLibraryFile of existingLibraryItem.libraryFiles) {
225	      // Find matching library file using path first and fallback to using inode value
226	      let matchingLibraryFile = this.libraryFiles.find(lf => lf.metadata.path === existingLibraryFile.metadata.path)
227	      if (!matchingLibraryFile) {
228	        matchingLibraryFile = this.libraryFiles.find(lf => lf.ino === existingLibraryFile.ino)
229	        if (matchingLibraryFile) {
230	          libraryScan.addLog(LogLevel.INFO, `Library file with path "${existingLibraryFile.metadata.path}" not found, but found file with matching inode value "${existingLibraryFile.ino}" at path "${matchingLibraryFile.metadata.path}"`)
231	        }
232	      }
233	
234	      if (!matchingLibraryFile) { // Library file removed
