246	      }
247	    }
248	
249	    // Log new library files found
250	    if (libraryFilesAdded.length) {
251	      this.hasChanges = true
252	      for (const libraryFile of libraryFilesAdded) {
253	        libraryScan.addLog(LogLevel.INFO, `New library file found with path "${libraryFile.metadata.path}" for library item "${existingLibraryItem.relPath}"`)
254	        if (libraryFile.isEBookFile) {
