266	      existingLibraryItem.libraryFiles.forEach((lf) => existingLibraryItem.size += lf.metadata.size)
267	
268	      existingLibraryItem.lastScan = Date.now()
269	      existingLibraryItem.lastScanVersion = packageJson.version
