271	      libraryScan.addLog(LogLevel.DEBUG, `Library item "${existingLibraryItem.relPath}" changed: [${existingLibraryItem.changed()?.join(',') || ''}]`)
272	
273	      if (this.hasLibraryFileChanges) {
274	        existingLibraryItem.changed('libraryFiles', true)
275	      }
276	      await existingLibraryItem.save()
277	      return true
278	    }
279	
280	    return false
281	  }
