283	  /**
284	   * Update existing library file with scanned in library file data
285	   * @param {string} libraryItemPath
286	   * @param {LibraryItem.LibraryFileObject} existingLibraryFile 
287	   * @param {import('../objects/files/LibraryFile')} scannedLibraryFile 
288	   * @param {import('./LibraryScan')} libraryScan
289	   * @returns {boolean} false if no changes
290	   */
291	  compareUpdateLibraryFile(libraryItemPath, existingLibraryFile, scannedLibraryFile, libraryScan) {
292	    let hasChanges = false
293	
294	    if (existingLibraryFile.ino !== scannedLibraryFile.ino) {
295	      existingLibraryFile.ino = scannedLibraryFile.ino
296	      hasChanges = true
297	    }
298	
299	    for (const key in existingLibraryFile.metadata) {
300	      if (existingLibraryFile.metadata[key] !== scannedLibraryFile.metadata[key]) {
301	        if (key !== 'path' && key !== 'relPath') {
302	          libraryScan.addLog(LogLevel.DEBUG, `Library file "${existingLibraryFile.metadata.relPath}" for library item "${libraryItemPath}" key "${key}" changed from "${existingLibraryFile.metadata[key]}" to "${scannedLibraryFile.metadata[key]}"`)
303	        } else {
304	          libraryScan.addLog(LogLevel.DEBUG, `Library file for library item "${libraryItemPath}" key "${key}" changed from "${existingLibraryFile.metadata[key]}" to "${scannedLibraryFile.metadata[key]}"`)
305	        }
306	        existingLibraryFile.metadata[key] = scannedLibraryFile.metadata[key]
307	        hasChanges = true
308	      }
309	    }
310	
311	    if (hasChanges) {
312	      existingLibraryFile.updatedAt = Date.now()
313	    }
314	
315	    return hasChanges
316	  }
317	
318	  /**
319	   * Check if existing audio file on Book was removed
320	   * @param {import('../models/Book').AudioFileObject} existingAudioFile 
321	   * @returns {boolean} true if audio file was removed
322	   */
323	  checkAudioFileRemoved(existingAudioFile) {
324	    if (!this.audioLibraryFilesRemoved.length) return false
325	    // First check exact path
326	    if (this.audioLibraryFilesRemoved.some(af => af.metadata.path === existingAudioFile.metadata.path)) {
327	      return true
328	    }
329	    // Fallback to check inode value
330	    return this.audioLibraryFilesRemoved.some(af => af.ino === existingAudioFile.ino)
331	  }
332	
333	  /**
334	   * Check if existing ebook file on Book was removed
335	   * @param {import('../models/Book').EBookFileObject} ebookFile 
336	   * @returns {boolean} true if ebook file was removed
337	   */
338	  checkEbookFileRemoved(ebookFile) {
339	    if (!this.ebookLibraryFiles.length) return true
340	
341	    if (this.ebookLibraryFiles.some(lf => lf.metadata.path === ebookFile.metadata.path)) {
342	      return false
343	    }
344	
345	    return !this.ebookLibraryFiles.some(lf => lf.ino === ebookFile.ino)
346	  }
347	
348	  /**
349	   * Set data parsed from filenames
350	   * 
351	   * @param {Object} bookMetadata 
352	   */
353	  setBookMetadataFromFilenames(bookMetadata) {
354	    const keysToMap = ['title', 'subtitle', 'publishedYear', 'asin']
355	    for (const key in this.mediaMetadata) {
356	      if (keysToMap.includes(key) && this.mediaMetadata[key]) {
357	        bookMetadata[key] = this.mediaMetadata[key]
358	      }
359	    }
360	
361	    if (this.mediaMetadata.authors?.length) {
362	      bookMetadata.authors = this.mediaMetadata.authors
363	    }
364	    if (this.mediaMetadata.narrators?.length) {
365	      bookMetadata.narrators = this.mediaMetadata.narrators
366	    }
367	    if (this.mediaMetadata.seriesName) {
368	      bookMetadata.series = [
369	        {
370	          name: this.mediaMetadata.seriesName,
371	          sequence: this.mediaMetadata.seriesSequence || null
372	        }
373	      ]
374	    }
375	  }
376	}
