16	/**
17	 * @typedef QuickMatchOptions
18	 * @property {string} [provider]
19	 * @property {string} [title]
20	 * @property {string} [author]
21	 * @property {string} [isbn] - This override is currently unused in Abs clients
22	 * @property {string} [asin] - This override is currently unused in Abs clients
23	 * @property {boolean} [overrideCover]
24	 * @property {boolean} [overrideDetails]
25	 */
26	
27	class Scanner {
28	  constructor() {}
29	
30	  /**
31	   *
32	   * @param {import('../routers/ApiRouter')} apiRouterCtx
33	   * @param {import('../models/LibraryItem')} libraryItem
34	   * @param {QuickMatchOptions} options
35	   * @returns {Promise<{updated: boolean, libraryItem: Object}>}
36	   */
37	  async quickMatchLibraryItem(apiRouterCtx, libraryItem, options = {}) {
38	    const provider = options.provider || 'google'
39	    const searchTitle = options.title || libraryItem.media.title
40	    const searchAuthor = options.author || libraryItem.media.authorName
41	
42	    // If overrideCover and overrideDetails is not sent in options than use the server setting to determine if we should override
43	    if (options.overrideCover === undefined && options.overrideDetails === undefined && Database.serverSettings.scannerPreferMatchedMetadata) {
44	      options.overrideCover = true
45	      options.overrideDetails = true
46	    }
47	
48	    let updatePayload = {}
49	    let hasUpdated = false
50	
51	    if (libraryItem.isBook) {
52	      const searchISBN = options.isbn || libraryItem.media.isbn
53	      const searchASIN = options.asin || libraryItem.media.asin
54	
55	      const results = await BookFinder.search(libraryItem, provider, searchTitle, searchAuthor, searchISBN, searchASIN, { maxFuzzySearches: 2 })
56	      if (!results.length) {
57	        return {
58	          warning: `No ${provider} match found`
59	        }
60	      }
61	      const matchData = results[0]
62	
63	      // Update cover if not set OR overrideCover flag
64	      if (matchData.cover && (!libraryItem.media.coverPath || options.overrideCover)) {
65	        Logger.debug(`[Scanner] Updating cover "${matchData.cover}"`)
66	        const coverResult = await CoverManager.downloadCoverFromUrlNew(matchData.cover, libraryItem.id, libraryItem.isFile ? null : libraryItem.path)
67	        if (coverResult.error) {
