69	        } else {
70	          libraryItem.media.coverPath = coverResult.cover
71	          libraryItem.media.changed('coverPath', true) // Cover path may be the same but this forces the update
72	          hasUpdated = true
73	        }
74	      }
75	
76	      const bookBuildUpdateData = await this.quickMatchBookBuildUpdatePayload(apiRouterCtx, libraryItem, matchData, options)
77	      updatePayload = bookBuildUpdateData.updatePayload
78	      if (bookBuildUpdateData.hasSeriesUpdates || bookBuildUpdateData.hasAuthorUpdates) {
79	        hasUpdated = true
80	      }
81	    } else if (libraryItem.isPodcast) {
82	      // Podcast quick match
83	      const results = await PodcastFinder.search(searchTitle)
84	      if (!results.length) {
85	        return {
86	          warning: `No ${provider} match found`
87	        }
88	      }
89	      const matchData = results[0]
90	
91	      // Update cover if not set OR overrideCover flag
92	      if (matchData.cover && (!libraryItem.media.coverPath || options.overrideCover)) {
93	        Logger.debug(`[Scanner] Updating cover "${matchData.cover}"`)
94	        const coverResult = await CoverManager.downloadCoverFromUrlNew(matchData.cover, libraryItem.id, libraryItem.path)
95	        if (coverResult.error) {
96	          Logger.warn(`[Scanner] Match cover "${matchData.cover}" failed to use: ${coverResult.error}`)
97	        } else {
98	          libraryItem.media.coverPath = coverResult.cover
99	          libraryItem.media.changed('coverPath', true) // Cover path may be the same but this forces the update
100	          hasUpdated = true
101	        }
102	      }
103	
104	      updatePayload = this.quickMatchPodcastBuildUpdatePayload(libraryItem, matchData, options)
105	    }
106	
107	    if (Object.keys(updatePayload).length) {
108	      Logger.debug('[Scanner] Updating details with payload', updatePayload)
109	      libraryItem.media.set(updatePayload)
110	      if (libraryItem.media.changed()) {
111	        Logger.debug(`[Scanner] Updating library item "${libraryItem.media.title}" keys`, libraryItem.media.changed())
112	        hasUpdated = true
113	      }
114	    }
115	
116	    if (hasUpdated) {
117	      if (libraryItem.isPodcast && libraryItem.media.feedURL) {
118	        // Quick match all unmatched podcast episodes
119	        await this.quickMatchPodcastEpisodes(libraryItem, options)
120	      }
