201	        if (key === 'narrator') {
202	          if (!libraryItem.media.narrators?.length || options.overrideDetails) {
203	            updatePayload.narrators = matchData[key]
204	              .split(',')
205	              .map((v) => v.trim())
206	              .filter((v) => !!v)
207	          }
208	        } else if (key === 'genres') {
209	          if (!libraryItem.media.genres.length || options.overrideDetails) {
210	            let genresArray = []
211	            if (Array.isArray(matchData[key])) genresArray = [...matchData[key]]
212	            else {
213	              // Genres should always be passed in as an array but just incase handle a string
214	              Logger.warn(`[Scanner] quickMatch genres is not an array ${matchData[key]}`)
215	              genresArray = matchData[key]
216	                .split(',')
217	                .map((v) => v.trim())
218	                .filter((v) => !!v)
219	            }
220	            updatePayload[key] = genresArray
221	          }
222	        } else if (key === 'tags') {
223	          if (!libraryItem.media.tags.length || options.overrideDetails) {
224	            let tagsArray = []
225	            if (Array.isArray(matchData[key])) tagsArray = [...matchData[key]]
226	            else
227	              tagsArray = matchData[key]
228	                .split(',')
