230	                .filter((v) => !!v)
231	            updatePayload[key] = tagsArray
232	          }
233	        } else if (!libraryItem.media[key] || options.overrideDetails) {
234	          updatePayload[key] = matchData[key]
235	        }
236	      }
237	    }
238	
239	    // Add or set author if not set
240	    let hasAuthorUpdates = false
241	    if (matchData.author && (!libraryItem.media.authorName || options.overrideDetails)) {
242	      if (!Array.isArray(matchData.author)) {
243	        matchData.author = matchData.author
244	          .split(',')
245	          .map((au) => au.trim())
246	          .filter((au) => !!au)
247	      }
248	      const authorIdsRemoved = []
249	      for (const authorName of matchData.author) {
250	        const existingAuthor = libraryItem.media.authors.find((a) => a.name.toLowerCase() === authorName.toLowerCase())
251	        if (!existingAuthor) {
252	          let author = await Database.authorModel.getByNameAndLibrary(authorName, libraryItem.libraryId)
253	          if (!author) {
254	            author = await Database.authorModel.create({
255	              name: authorName,
256	              lastFirst: Database.authorModel.getLastFirst(authorName),
257	              libraryId: libraryItem.libraryId
258	            })
259	            SocketAuthority.emitter('author_added', author.toOldJSON())
260	            // Update filter data
261	            Database.addAuthorToFilterData(libraryItem.libraryId, author.name, author.id)
262	          }
263	          await Database.bookAuthorModel
264	            .create({
265	              authorId: author.id,
266	              bookId: libraryItem.media.id
267	            })
268	            .then(() => {
269	              Logger.info(`[Scanner] quickMatchBookBuildUpdatePayload: Added author "${author.name}" to "${libraryItem.media.title}"`)
270	              libraryItem.media.authors.push(author)
271	              hasAuthorUpdates = true
272	            })
273	        }
274	        const authorsRemoved = libraryItem.media.authors.filter((a) => !matchData.author.find((ma) => ma.toLowerCase() === a.name.toLowerCase()))
275	        if (authorsRemoved.length) {
276	          for (const author of authorsRemoved) {
277	            await Database.bookAuthorModel.destroy({ where: { authorId: author.id, bookId: libraryItem.media.id } })
278	            libraryItem.media.authors = libraryItem.media.authors.filter((a) => a.id !== author.id)
279	            authorIdsRemoved.push(author.id)
280	            Logger.info(`[Scanner] quickMatchBookBuildUpdatePayload: Removed author "${author.name}" from "${libraryItem.media.title}"`)
281	          }
282	          hasAuthorUpdates = true
283	        }
284	      }
285	
286	      // For all authors removed from book, check if they are empty now and should be removed
287	      if (authorIdsRemoved.length) {
