289	      }
290	    }
291	
292	    // Add or set series if not set
293	    let hasSeriesUpdates = false
294	    if (matchData.series && (!libraryItem.media.seriesName || options.overrideDetails)) {
295	      if (!Array.isArray(matchData.series)) matchData.series = [{ series: matchData.series, sequence: matchData.sequence }]
296	      const seriesIdsRemoved = []
297	      for (const seriesMatchItem of matchData.series) {
