435	  async matchLibraryItemsChunk(apiRouterCtx, library, libraryItems, libraryScan) {
436	    for (let i = 0; i < libraryItems.length; i++) {
437	      const libraryItem = libraryItems[i]
438	
439	      if (libraryItem.media.asin && library.settings.skipMatchingMediaWithAsin) {
