478	    if (LibraryScanner.isLibraryScanning(library.id)) {
479	      Logger.error(`[Scanner] Library "${library.name}" is already scanning`)
480	      return
481	    }
482	
483	    const limit = 100
484	    let offset = 0
485	
486	    const libraryScan = new LibraryScan()
487	    libraryScan.setData(library, 'match')
488	    LibraryScanner.librariesScanning.push(libraryScan.libraryId)
489	    const taskData = {
